from pathlib import Path
import json, html, hashlib, shutil, re, importlib.util
spec=importlib.util.spec_from_file_location('document_library',Path(__file__).resolve().parents[1]/'packages/content/document-library.py')
library=importlib.util.module_from_spec(spec);spec.loader.exec_module(library)
ROOT=Path(__file__).resolve().parents[1]
data=json.loads((ROOT/'canonical/site-state.json').read_text())
research_spec=importlib.util.spec_from_file_location('research_schema',ROOT/'packages/research-schema/validate.py')
research_schema=importlib.util.module_from_spec(research_spec);research_spec.loader.exec_module(research_schema)
records,cycle_manifests=research_schema.validate(ROOT)
manifest=cycle_manifests['cycles/cycle-01/manifest.json']
data['cycle']={'number':f'{manifest["cycle_number"]:02d}','title':manifest['title'],'status':manifest['status'],'obligations':[o['description'] for o in manifest['obligations']],'resolved_keys':[i for i,o in enumerate(manifest['obligations']) if o['resolved']]}
data['questions']=[[q['aliases'][0],q['title'],q['question'],q['status']] for q in sorted(records.values(),key=lambda q:q['id']) if q['type']=='Question']
for package in data['packages']:
 record=records['RP-'+package['id'][2:]]
 package['title']=record['title']
 package['status']=record['status']
esc=html.escape
cycle=data['cycle']
resolved=cycle['resolved_keys']
assert cycle['obligations'] and len(set(resolved)) == len(resolved)
assert all(isinstance(i,int) and 0 <= i < len(cycle['obligations']) for i in resolved)
progress=sum(o['weight'] for o in manifest['obligations'] if o['resolved'])/sum(o['weight'] for o in manifest['obligations'])
assert (progress == 1) == (cycle['status'] in ('CLOSED','PUBLISHED'))
completion=f"{len(resolved)} / {len(cycle['obligations'])} obligations resolved ({progress*100:.1f}%)."
origins=json.loads((ROOT/'canonical/site-origins.json').read_text()) if (ROOT/'canonical/site-origins.json').exists() else {'org':'http://localhost:4173','net':'http://localhost:4174'}
css_library=(ROOT/'packages/ui-foundation/document-library.css').read_text()
logo='<svg viewBox="0 0 56 56" aria-hidden="true"><path d="M12 32a19 19 0 1 1 32 0M8 41q20-9 40 0" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round"/></svg>'

ring=f'<div class="cycle-ring" role="img" aria-label="Cycle {cycle["number"]}: {cycle["status"]}, {completion}"><svg class="progress" viewBox="0 0 100 100" aria-hidden="true"><circle cx="50" cy="50" r="46" fill="none" stroke="currentColor" stroke-width="5" pathLength="100" stroke-dasharray="{progress*100} 100" transform="rotate(-90 50 50)"/></svg><span>{cycle["number"]}</span></div>'
css='''.skip-link{position:absolute;left:16px;top:-100px;padding:12px;background:white;color:#152235;z-index:5}.skip-link:focus{top:12px}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f5f7fa;color:#152235;font:17px/1.65 system-ui,-apple-system,sans-serif}a{color:inherit;text-underline-offset:5px}a:hover{color:#245fbd}a:focus-visible{outline:3px solid #edb654;outline-offset:5px}header,main,footer{max-width:1240px;margin:auto;padding:0 48px}header{display:flex;align-items:center;justify-content:space-between;gap:24px;padding-top:28px;padding-bottom:28px;border-bottom:1px solid #d9e0e9}.brand{display:flex;gap:12px;align-items:center;text-decoration:none;font-size:23px;letter-spacing:.12em;font-weight:650}.brand svg{width:44px;height:44px}nav{display:flex;flex-wrap:wrap;gap:22px;font-size:14px}nav a{text-decoration:none}nav a[aria-current]{border-bottom:2px solid currentColor}main{padding-top:64px;padding-bottom:90px}.eyebrow,.label{font:13px/1.5 ui-monospace,monospace;letter-spacing:.1em;text-transform:uppercase;color:#526985}.hero{display:grid;grid-template-columns:1fr 280px;gap:70px;align-items:center;margin-bottom:60px}h1{font:normal clamp(38px,5.5vw,70px)/1.09 Georgia,serif;letter-spacing:-.035em;margin:20px 0 28px;max-width:820px}h2{font:normal 34px/1.25 Georgia,serif;margin:0 0 22px}h3{font-size:21px;line-height:1.4;margin:10px 0 15px}p{max-width:760px;margin:0 0 22px}.lead{font-size:21px;color:#40536c}.cycle-ring{width:174px;height:174px;border:8px solid #dce3ed;border-radius:50%;display:grid;place-items:center;margin:0 auto 22px;position:relative}.cycle-ring:before{content:'';position:absolute;top:-8px;left:calc(50% - 4px);width:8px;height:8px;background:#203f68;border-radius:50%}.cycle-ring .progress{position:absolute;inset:-8px;width:calc(100% + 16px);height:calc(100% + 16px);color:#507caf}.cycle-ring span{font:50px Georgia,serif}.cycle-panel{text-align:center;border-left:1px solid #d9e0e9;padding-left:30px}.cycle-panel p{font-size:14px}.tag{display:inline-block;font:13px ui-monospace,monospace;padding:6px 10px;border:1px solid #cbd7e5;border-radius:3px;margin:0 0 14px;color:#405b7d}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}.card{padding:28px;border:1px solid #d9e0e9;background:white}.card p{font-size:16px}.card a{text-decoration:none}.card .id{font:14px ui-monospace,monospace;color:#496a91}.section{border-top:1px solid #d9e0e9;padding-top:36px;margin-top:46px}.row{display:grid;grid-template-columns:130px 1fr;gap:28px;padding:24px 0;border-bottom:1px solid #d9e0e9}.row p{margin:0;font-size:16px}.empty{border-left:3px solid #567dae;padding:22px 28px;background:#eaf0f7}.prose{max-width:820px}.prose h2{margin-top:45px}.prose li{margin:10px 0}.actions{display:flex;gap:24px;flex-wrap:wrap;margin:26px 0}.button{display:inline-block;background:#193b64;color:white;padding:12px 20px;text-decoration:none}.button:hover{background:#285484;color:white}footer{border-top:1px solid #d9e0e9;padding-top:25px;padding-bottom:34px;font-size:14px;color:#60718a;display:flex;gap:25px;justify-content:space-between}.net{background:#101925;color:#e3ebf6}.net header,.net .section,.net footer,.net .row{border-color:#2a3a4f}.net nav a:hover,.net a:hover{color:#9ebff1}.net .brand{color:#f0f5fc}.net h1,.net h2{font-family:system-ui,sans-serif;letter-spacing:-.04em}.net h1{font-size:clamp(34px,4vw,54px)}.net .lead{color:#a8b9cf}.net .eyebrow,.net .label,.net .card .id{color:#94afd2}.net .card{background:#152235;border-color:#2a3a4f}.net .tag{color:#a9c5e8;border-color:#3b536f}.net .cycle-panel{border-color:#2a3a4f}.net .cycle-ring{border-color:#2b3b51}.net .cycle-ring:before{background:#a2c9ff}.net .empty{background:#1b2d44;border-color:#8eb6eb}.net .button{background:#aac8ee;color:#101925}.obligations{list-style:none;padding:0}.obligations li{display:flex;gap:18px;border-bottom:1px solid #2a3a4f;padding:15px 0}.obligations .key{font:13px ui-monospace,monospace;color:#91acca;min-width:45px}.muted{color:#70839c}code{font-size:14px}@media(max-width:800px){header,main,footer{padding-left:22px;padding-right:22px}header{align-items:flex-start;flex-direction:column}nav{gap:14px}main{padding-top:38px}.hero{grid-template-columns:1fr;gap:28px}.cycle-panel{border-left:0;border-top:1px solid #d9e0e9;padding:28px 0 0;display:flex;gap:24px;text-align:left;align-items:center}.cycle-ring{width:110px;height:110px;min-width:110px;margin:0}.cycle-ring span{font-size:36px}.grid{grid-template-columns:1fr}.row{grid-template-columns:1fr;gap:8px}footer{flex-direction:column}.lead{font-size:18px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}'''
def href(site,path='/'): return origins[site].rstrip('/')+path
def panel(): return f'<aside class="cycle-panel">{ring}<div><div class="label">Cycle 01 · {cycle["status"]}</div><h3>Foundations Under Test</h3><p>{completion}<br>RP002A reviewed and completed; broader questions remain open.</p></div></aside>'
def hero(label,title,desc,with_ring=True): return f'<section class="hero"><div><div class="eyebrow">{label}</div><h1>{title}</h1><p class="lead">{desc}</p></div>{panel() if with_ring else ""}</section>'
def cards(): return '<div class="grid">'+''.join(f'<article class="card"><div class="id">{p["id"]} · {p["status"]}</div><h3><a href="{href("net","/rp/"+p["id"]+"/")}">{p["title"]}</a></h3><p>{p["question"]}</p></article>' for p in data['packages'])+'</div>'
def changes(): return ''.join(f'<article class="row"><div class="label">{d}</div><div><h3>{t}</h3><p>{b}</p></div></article>' for d,t,b in data['changes'])
def page(site,path,title,body):
 if site=='org' and 'class="cycle-panel"' not in body:
  body=body.replace('class="hero"','class="hero hero--text"',1)
 navs={'org':[('/', 'Program'),('/questions/','Questions'),('/knowledge/','Knowledge'),('/methods/','Methods'),('/publications/','Publications'),('/changes/','Changes'),('/sources/','Documents')], 'net':[('/','Laboratory'),('/cycle/01/','Cycle 01'),('/research/','Packages'),('/results/','Results'),('/journal/','Journal'),('/sources/','Documents')]}
 other='net' if site=='org' else 'org'; otherlabel='Open laboratory' if site=='org' else 'Knowledge & publication'
 nav=''.join(f'<a href="{p}"'+(' aria-current="page"' if p==path else '')+f'>{t}</a>' for p,t in navs[site])+f'<a href="{href(other)}">{otherlabel}</a>'
 favicon='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 56 56"><rect width="56" height="56" fill="#152235"/><path d="M12 32a19 19 0 1 1 32 0M8 41q20-9 40 0" fill="none" stroke="#fff" stroke-width="3"/></svg>'
 from urllib.parse import quote
 stylesheet='/style.css?v='+hashlib.sha256((css+css_library+((ROOT/'packages/ui-foundation/org-layout.css').read_text() if site=='org' else '')).encode()).hexdigest()[:12]
 doc=f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} — Autorite</title><meta name="description" content="Autorite open research program: questions, methods and a documented research process."><link rel="canonical" href="{href(site,path)}"><link rel="icon" href="data:image/svg+xml,{quote(favicon)}"><link rel="stylesheet" href="{stylesheet}"></head><body class="{site}"><a class="skip-link" href="#main">Skip to content</a><header><a class="brand" href="/">{logo}AUTORITE</a><nav aria-label="Main navigation">{nav}</nav></header><main id="main">{body}</main><footer><span>Open-ended inquiry · Updated {esc(data["updated_at"])}</span><span><a href="/sources/">Documents</a> · <a href="{href(other)}">{otherlabel}</a> · <a href="https://github.com/omasim/Autorite">GitHub</a> · <a href="https://omerasim.com">omerasim</a></span></footer></body></html>'
 dest=ROOT/'apps'/site/'dist'/path.strip('/')/'index.html';dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(doc)
 routes[site].append(path)
routes={'org':[],'net':[]}
for site in routes:
 dist=ROOT/'apps'/site/'dist'; dist.mkdir(parents=True,exist_ok=True);(dist/'style.css').write_text(css + css_library + ((ROOT/'packages/ui-foundation/org-layout.css').read_text() if site=='org' else ''))
page('org','/','Open-ended inquiry',hero('Autorite / Research Program','Begin with questions.<br>Follow the evidence.','An open research program on continuation, representation, reachability and realized history. The first Cycle investigates the testable boundaries of these questions.')+'<div class="actions"><a class="button" href="/questions/">Research questions</a><a href="'+href('net','/cycle/01/')+'">Follow Cycle 01</a></div><section class="section"><h2>Questions before architecture.</h2><p>Autorite keeps the scope of claims, their assumptions and the evidence that could change them visible. Negative results are part of the research record. The program makes no claim to a completed theory.</p><p>The audited baseline is frozen. RP002A completed its separately authorized second confirmation: 60 units and 120 learned fits, with seven conditional decisions under the frozen analysis. The first incomplete attempt remains preserved. RP002A is CLOSED after its scoped internal review; Cycle 01 remains ACTIVE. <a href="'+href('net','/sources/rp002a-package-review/')+'">Read the package review</a>.</p></section><section class="section"><h2>Cycle 01 research</h2>'+cards()+'</section><section class="section"><h2>Recent changes</h2>'+changes()+'</section>')
page('org','/questions/','Research questions',hero('Foundational questions','Which distinctions<br>must be preserved?','The independence and completeness of this question set are not assumed.',False)+'<div class="grid">'+''.join(f'<article class="card"><div class="id">{q[0]} · {q[3]}</div><h3>{q[1]}</h3><p>{q[2]}</p>'+('<p class="muted">Reduction to Q3 remains a candidate.</p>' if q[0]=='Q4' else '')+'</article>' for q in data['questions'])+'</div><p class="section">ACTIVE labels indicate the question focus in the baseline. They do not mean experiments have started.</p>')
page('org','/knowledge/','Current knowledge',hero('Knowledge status','Keep the untested<br>visible.','Evidence keeps its scope and assumptions attached.',False)+'<div class="empty"><h2>One audited finite benchmark.</h2><p>RP002A completed 60 independent units and 120 learned fits. Two history-based algorithms meet the frozen benefit margin in E1; four E0/E2 comparisons meet the frozen equivalence margin. The B2-versus-B1 benefit comparison is indeterminate under its .01-nat margin.</p><p>These are conditional decisions for specified algorithms and synthetic generators, with independence and normal-theory assumptions. They establish no recurrence necessity, universal memory or broad theory. Cycle 01 remains ACTIVE; '+completion+' RP002A is CLOSED after internal package review.</p><a href="'+href('net','/sources/rp002a-confirmatory-002/')+'">Read the full audited report</a><p><a href="'+href('net','/sources/rp002a-package-review/')+'">Package interpretation and disposition</a></p></div><section class="section"><h2>Read the research record</h2><p><a href="'+href('net','/sources/rp002a-confirmatory-002-protocol/')+'">Second frozen protocol</a> · <a href="'+href('net','/sources/rp002a-confirmatory-001/')+'">Preserved incomplete first attempt</a></p></section><section class="section"><h2>What accompanies a claim</h2><p>Scope, assumptions, supporting and challenging evidence, limitations and conditions that could change the interpretation remain visible. No broad Claim has been promoted from this benchmark.</p></section>')
page('org','/methods/','Research method',hero('Methods / Baseline v0.1','Traceable claims.<br>Visible boundaries.','One research record, with separate knowledge and laboratory views.',False)+'<div class="prose"><h2>Research principles</h2><ul><li>Questions come before architecture.</li><li>Scope and assumptions remain attached to the claim.</li><li>Prior-art collision precedes novelty claims.</li><li>Negative results and invalidated runs remain visible.</li><li>Cross-domain similarity alone is not unification.</li><li>Use the weakest sufficient formal structure for the problem.</li></ul><h2>An open program, finite Cycles</h2><p>The program has no terminal closed state. Each Cycle has finite obligations. The ring tracks documented resolutions rather than elapsed time. A closed Cycle publishes its synthesis, open questions and a frozen knowledge snapshot.</p><h2>Sources and change history</h2><p>The updated baseline is authoritative. Source documents remain unchanged, with implementation clarifications recorded separately. The canonical research repository is omasim/Autorite. Both public sites are generated from its shared research and publication sources.</p><a href="/sources/">Method and contract documents</a></div>')
page('org','/publications/','Publications',hero('Publications','The working framework.<br>Future syntheses.','Preparation documents are presented separately from research results.',False)+'<div class="empty"><h2>The Cycle 01 synthesis has not been published.</h2><p>The synthesis and frozen knowledge snapshot will be published at Cycle closure. The current baseline is a research design.</p><a href="/sources/">Read the baseline documents</a></div>')
page('org','/changes/','Changes',hero('Change history','What changed,<br>and why?','Follow research decisions, reports and documented changes here.',False)+changes())
page('net','/','Open laboratory',hero('Open Laboratory / First package completed','Cycle 01<br>Foundations under test.','Four research packages and a parallel archaeology workstream. RP002A completed its freshly authorized second confirmation: 60 units, 120 fits and seven conditional decisions. The first incomplete attempt remains preserved.')+'<div class="actions"><a class="button" href="/sources/rp002a-confirmatory-002/">Read the audited benchmark</a><a href="/cycle/01/">Cycle obligations</a><a href="/journal/">Process journal</a></div><section class="section"><h2>Research packages</h2>'+cards()+'</section><section class="section"><h2>Evidence and remaining work</h2><div class="grid"><article class="card"><div class="id">RP002A</div><h3>Fixed scope, visible assumptions</h3><p>Two benefit, four equivalent and one indeterminate decision under the frozen .01-nat margins. The scoped package is CLOSED after an explicit internal review. Broader questions and the other packages remain open. <a href="/sources/rp002a-package-review/">Read the disposition review</a>.</p></article><article class="card"><div class="id">DAM X</div><h3>Awaiting source documents</h3><p>Only an archaeology template exists. Historical material will be reconstructed only from supplied sources.</p></article></div></section>')
def obligation_row(i,o):
 status=esc(o['resolution'].replace('_',' ').capitalize()) if o['resolved'] else 'Open · no resolution on record'
 evidence=''
 if o['resolved']:
  links=[]
  for ref in o['evidence_refs']:
   label={'research/RP002A/PACKAGE_REVIEW.md':'Package review','research/RP002A/CONFIRMATORY_002_REPORT.md':'Completed benchmark','research/RP002A/confirmation-002/result/RECORD.md':'Audited Result','docs/decisions/DECISION-0004_RP002A_DISPOSITION.md':'Disposition decision'}.get(ref,Path(ref).stem.replace('_',' ').title())
   links.append(f'<a href="https://github.com/omasim/Autorite/blob/main/{esc(ref,quote=True)}">{esc(label)}</a>')
  if o['decision_ref']:
   links.append(f'<a href="https://github.com/omasim/Autorite/blob/main/graph/decisions/{esc(o["decision_ref"],quote=True)}.md">{esc(o["decision_ref"])}</a>')
  evidence='<br><small>Evidence: '+' · '.join(links)+'</small>'
 return f'<li><span class="key">{i:02d}</span><span>{esc(o["description"])}<br><small class="muted">{status}</small>{evidence}</span></li>'
page('net','/cycle/01/','Cycle 01',hero('Cycle / 01','Foundations Under Test','Active · Obligation-based progress · First bounded research execution: 2026-10-08.')+f'<h2>{len(resolved)} resolved · {len(cycle["obligations"])-len(resolved)} open obligations</h2><ul class="obligations">'+''.join(obligation_row(i,o) for i,o in enumerate(manifest['obligations'],1))+'</ul><section class="section"><h2>What does closure mean?</h2><p>An obligation may be completed, documented as validly blocked, or explicitly transferred. Negative results can resolve an obligation; missing documentation and review cannot.</p><p>The ring is computed from documented resolutions. Completing the final close bundle closes the Cycle. The full ring remains after publication.</p></section>')
page('net','/research/','Research packages',hero('Cycle 01 / Packages','Four boundaries<br>to investigate.','Each package is tracked through its question, scope, protocol and interpretation limits.',False)+cards())
for p in data['packages']:
 body=hero(p['id']+' / '+p['status'],p['title'],p['question'],False)+f'<div class="prose"><h2>Cases and controls</h2><p>{p["cases"]}</p><h2>Interpretation limit</h2><p>{p["limit"]}</p><h2>Execution status</h2><p>Confirmatory execution is pending. Operational protocol details and prior-art collision remain open.</p><div class="actions"><a href="/sources/{Path(p["source"]).stem.lower().replace("_","-")}/">Read protocol</a><a href="/sources/implementation-research-execution-readiness/">Pre-execution readiness checklist</a></div><h2>Runs, results and deviations</h2><div class="empty">No confirmatory records yet.</div></div>'
 if p['id']=='RP002A':
  body=body.replace('Confirmatory execution is pending. Operational protocol details and prior-art collision remain open.','Calibration, fresh variance selection and the separately authorized second confirmation completed. All 60 units and seven frozen decisions replay; the first incomplete attempt remains preserved. The scoped package is CLOSED under D-0004 after explicit internal review.').replace('No confirmatory records yet.','Test TST-RP002A002 has audited Result R-RP002A002 (VALID): two benefit, four equivalent and one indeterminate decision under the fixed conditional analysis. No broad Claim or Cycle closure.').replace('Read protocol</a>','Read baseline preregistration</a>')
  body += '<section class="section"><h2>Package disposition - completed</h2><p>D-0004 accepts the defined finite commitment after internal review. RP002A is CLOSED; Q-3 and Q-4 remain ACTIVE. Only the RP002A disposition obligation is resolved. The indeterminate B2-versus-B1 outcome remains unchanged.</p><div class="actions"><a class="button" href="/sources/rp002a-package-review/">Read package review</a><a href="/sources/rp002a-package-decision/">Read Decision D-0004</a></div></section>'
  body += '<section class="section"><h2>Second confirmation completed and audited</h2><p>60 units, 120 learned fits and 484 hashed outputs. Two benefit, four equivalent and one indeterminate decision under the frozen .01-nat rules and conditional normal-theory assumptions. No trace warnings, broad Claim or Cycle closure.</p><div class="actions"><a class="button" href="/sources/rp002a-confirmatory-002/">Read the complete benchmark</a><a href="/sources/rp002a-confirmatory-002-protocol/">Second frozen protocol</a></div></section>'
  body += '<section class="section"><h2>First confirmation attempt — incomplete</h2><p>36/60 complete units and 73 saved fit traces are preserved and audited. A clock incident crossed the four-hour wall allowance; no aggregate decisions for that attempt. A separately authorized second attempt is documented independently.</p><div class="actions"><a class="button" href="/sources/rp002a-confirmatory-001/">Read interruption review</a><a href="/sources/rp002a-confirmatory-protocol/">Frozen protocol</a><a href="/sources/rp002a-calibration-001/">Synthetic calibration</a><a href="/sources/rp002a-target-variance-001/">Variance selection</a></div></section>'
 if p['id']=='RP002A': body += '<section class="section"><h2>First exploratory pilot completed</h2><p>One bounded engineering pilot completed with verified artifacts. No scientific hypothesis decision or Cycle resolution.</p><a href="/sources/rp002a-pilot-001/">Read pilot review and raw-artifact links</a></section>'
 if p['id']=='RP002A': body += '<section class="section"><h2>Convergence stage completed</h2><p>Twenty independent units and 40 learned-model fits completed with verified artifacts. Many validation traces improved near the epoch cap; settled optimization is not established.</p><a href="/sources/rp002a-convergence-001/">Read the exploratory stage review</a><p>The separately approved longer-budget stage also completed: 40 fits in about 6 minutes 24 seconds. Twelve near-cap warnings remain.</p><a href="/sources/rp002a-convergence-002-plan/">Read the frozen longer-budget protocol</a><p><a href="/sources/rp002a-convergence-002/">Read the longer-budget stage review</a></p><p><a href="/sources/rp002a-budget-warning-review/">Review the remaining budget warnings</a><br><a href="/sources/rp002a-budget-transfer-plan/">Read the frozen target-data-size feasibility protocol</a></p><p>Six target-size fits completed in 5 minutes 48 seconds with no predeclared warning. One replicate per world supplies no variance or confirmatory conclusion.</p><a href="/sources/rp002a-budget-transfer-001/">Read the feasibility review</a><p><a href="/sources/rp002a-uncertainty-design/">Review uncertainty and replicate-count design</a></p></section>'
